<script setup lang="ts">
import { onUnmounted, ref } from 'vue';
import { useAccess } from './access';
import type { Api, MessageTemplate, TemplateDefinition, TemplateSession } from './types';
const {operate}=useAccess();
const props=defineProps<{api:Api;busy:boolean;session:TemplateSession;mutate:(a:()=>Promise<unknown>,n:string)=>Promise<boolean>}>();
const items=ref<MessageTemplate[]>([]),variables=ref<string[]>([]),loading=ref(false),error=ref(''),preview=ref<{title:string;summary:string;eventType:string}|null>(null),example=ref('这是一条模板预览内容。');
const deleting=ref<MessageTemplate|null>(null),deleteName=ref('');
let alive=true,g=0,c:AbortController|undefined;
const clone=(v:TemplateDefinition):TemplateDefinition=>JSON.parse(JSON.stringify(v)) as TemplateDefinition;
async function load(){c?.abort();const control=new AbortController();c=control;const current=++g;loading.value=true;error.value='';try{const data=await props.api<{items:MessageTemplate[];variables:string[]}>('templates','GET',undefined,control.signal);if(alive&&g===current){items.value=data.items;variables.value=data.variables;}}catch(e){if(alive&&g===current&&!control.signal.aborted){items.value=[];error.value=e instanceof Error?e.message:'读取模板失败';}}finally{if(alive&&g===current)loading.value=false;}}
function edit(t?:MessageTemplate){const s=props.session;s.id=t?.templateId||crypto.randomUUID();s.version=t?.version||0;s.draft=t?clone(t.definition):{name:'',title:'{title}',summary:'{summary}',icon:'text',sound:'none',durationSeconds:8};s.pending=null;s.uncertain=false;preview.value=null;}
async function save(){const s=props.session;if(!s.draft||props.busy)return;const body=s.pending||{expectedVersion:s.version,definition:clone(s.draft)};s.pending=body;const ok=await props.mutate(async()=>{const result=await props.api<MessageTemplate>(`templates/${s.id}`,'PUT',body);if(result.templateId!==s.id||result.deleted)throw new Error('未确认模板保存结果');},'模板已保存，仅影响新投递。');if(alive){if(ok){s.draft=null;s.pending=null;s.uncertain=false;}else s.uncertain=true;await load();}}
async function check(){const s=props.session;await props.mutate(async()=>{const result=await props.api<MessageTemplate>(`templates/${s.id}`);if(s.pending&&!result.deleted&&Object.entries(s.pending.definition).every(([k,v])=>result.definition[k as keyof TemplateDefinition]===v)){if(alive){s.draft=null;s.pending=null;s.uncertain=false;}}else throw new Error('当前模板不同，请关闭草稿后重新读取。');},'已核对模板。');if(alive)await load();}
async function render(t?:MessageTemplate){const d=t?.definition||props.session.draft;if(!d)return;await props.mutate(async()=>{const result=await props.api<{title:string;summary:string;eventType:string}>('templates/preview','POST',{definition:d,message:{connectorId:'preview',source:'preview',eventId:crypto.randomUUID(),eventType:'manual.test',title:'预览标题',content:example.value,summary:example.value,sender:'示例用户'}});if(alive)preview.value=result;},'预览已生成，未发送消息。');}
async function remove(){const t=deleting.value;if(!t||deleteName.value!==t.definition.name)return;await props.mutate(async()=>{await props.api(`templates/${t.templateId}?expectedVersion=${t.version}`,'DELETE');if(alive)deleting.value=null;},'模板已删除，已有投递保持原快照。');if(alive)await load();}
void load();onUnmounted(()=>{alive=false;g++;c?.abort();});
</script>
<template><section><div class="section-heading"><div><h1>模板</h1><p>标题、摘要与设备卡片预览</p></div><div class="management-actions"><button class="text-button" :disabled="busy||loading" @click="load">刷新模板</button><button v-if="operate" class="secondary" :disabled="busy||loading||!!error||!!session.draft" @click="edit()">创建模板</button></div></div><p v-if="loading" role="status">正在读取模板…</p><p v-if="error" class="feedback error" role="alert">{{error}}</p>
<form v-if="session.draft" class="inline-form" aria-label="模板编辑" @submit.prevent="save"><h2>{{session.version?'编辑模板':'创建模板'}}</h2><p v-if="session.uncertain" role="status">保存结果未确认，重试原版本或只读核对。</p><fieldset :disabled="busy||loading||!!session.pending" style="border:0;padding:0;margin:0"><label>名称<input v-model="session.draft.name" required maxlength="80"></label><label class="spaced">标题模板<input v-model="session.draft.title" required maxlength="512"></label><label class="spaced">摘要模板<textarea v-model="session.draft.summary" required maxlength="8192"></textarea></label><label class="spaced">卡片类型<select v-model="session.draft.icon"><option value="text">文本</option><option value="comment">评论</option><option value="alert">告警</option><option value="growth">成长</option><option value="system">系统</option></select></label></fieldset><p class="scope-note">变量：{{variables.map(v=>'{'+v+'}').join('、')}}。当前设备契约为无提示音、显示 8 秒，标题 96 字节、摘要 180 字节。</p><div class="form-footer"><button type="button" class="text-button" :disabled="busy" @click="session.draft=null;session.pending=null;session.uncertain=false">关闭模板草稿</button><div class="management-actions"><button v-if="session.pending" type="button" class="secondary" :disabled="busy" @click="check">核对当前模板</button><button class="primary" :disabled="busy||loading||!!error">{{session.uncertain?'重试原模板保存':'保存模板'}}</button></div></div></form>
<div v-if="!loading&&!error" class="record-list spaced"><p v-if="!items.length" class="empty-state">暂无模板</p><article v-for="t in items" :key="t.templateId" class="record-card"><div class="record-heading"><h2>{{t.definition.name}}</h2><span class="badge">版本 {{t.version}}</span></div><p>{{t.definition.title}}</p><div class="management-actions"><button class="text-button" :disabled="busy" @click="render(t)">预览此模板</button><button v-if="operate" class="text-button" :disabled="busy||!!session.draft" @click="edit(t)">编辑模板</button><button v-if="operate" class="text-button" :disabled="busy||!!session.draft" @click="deleting=t;deleteName=''">删除模板</button></div></article></div>
<form v-if="deleting" class="inline-form spaced" @submit.prevent="remove"><label>输入模板名“{{deleting.definition.name}}”<input v-model="deleteName" :disabled="busy"></label><p>被路由引用的模板不能删除；已有投递不会重写。</p><div class="form-footer"><button type="button" class="text-button" :disabled="busy" @click="deleting=null">取消删除模板</button><button class="primary" :disabled="busy||deleteName!==deleting.definition.name">确认删除模板</button></div></form>
<div class="inline-form spaced"><h2>变量预览</h2><label>示例内容<textarea v-model="example" maxlength="8192"></textarea></label><button class="secondary spaced" :disabled="busy||!session.draft||!example" @click="render()">预览当前草稿</button><article v-if="preview" class="record-card spaced" aria-label="模板预览结果"><h3>{{preview.title}}</h3><p style="white-space:pre-wrap">{{preview.summary}}</p><span class="muted">{{preview.eventType}} · 仅预览，未发送</span></article></div>
</section></template>
